3	// End-to-end regression coverage for the `alerts generate` and
4	// `alerts history` command entry points, focused on threshold-reduction
5	// backfill: a finding archived below the generation threshold leaves no
6	// processing record, so lowering the threshold later must still produce it
7	// exactly once, while identities already processed under the higher
8	// threshold are never re-emitted. The tests drive the real CLI (forked
9	// test binary, see TestMain), parse the stdout JSON the way a user script
10	// would, and confirm through `alerts history` and `report` that records
11	// keep their first-processing threshold, channel, block identity,
12	// conclusion, detection version and raw swap evidence — even when a
13	// different rule version is enabled between the two generations.
14	// Everything runs offline against archive directories under t.TempDir.
15	
16	import (
17		"encoding/json"
18		"os"
19		"path/filepath"
20		"strings"
21		"testing"
22	
23		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
24	)
25	
26	// alertSwap builds one swap record with distinctive raw values so the
27	// tests can prove evidence keeps every original field and number.
28	func alertSwap(tx, pool, trader string, in, out, gas int64, index int) cliSwap {
29		return map[string]any{
30			"TxHash": tx, "Pool": pool, "Trader": trader,
31			"In": in, "Out": out, "GasPrice": gas, "Index": index,
32		}
33	}
34	
35	// setupAlertsCLIArchive archives one block on chain "1" (hash 0xa, height
36	// 10) under the built-in rules, carrying two conclusions and no matching
37	// suppression condition:
38	//
39	//	p1: 0xf (bot, gas 90) / 0xv (user, gas 10) / 0+k (bot, gas 80)
40	//	    -> sandwich on 0xv, severity 3
41	//	p2: 0+w (whale, gas 50) / 0xd (user, gas 10)
42	//	    -> displacement on 0xd, severity 2
43	//
44	// The source input file is deleted before returning: everything the tests
45	// assert afterwards must come from the archive alone.
46	func setupAlertsCLIArchive(t *testing.T) (dir string) {
47		t.Helper()
48		dir = t.TempDir()
49		inputPath := filepath.Join(t.TempDir(), "blocks.jsonl")
50		line := cliBlockLine("1", "0xa", 10,
51			alertSwap("0xf", "p1", "bot", 500, 480, 90, 0),
52			alertSwap("0xv", "p1", "user", 200, 188, 10, 1),
53			alertSwap("0+k", "p1", "bot", 480, 505, 80, 2),
54			alertSwap("0+w", "p2", "whale", 700, 690, 50, 3),
55			alertSwap("0xd", "p2", "user", 300, 295, 10, 4),
56		)
57		if err := os.WriteFile(inputPath, []byte(line+"\n"), 0o644); err != nil {
58			t.Fatal(err)
59		}
60		if _, err := mevwatch.ReplayFile(inputPath, dir); err != nil {
61			t.Fatalf("ReplayFile: %v", err)
62		}
63		if err := os.Remove(inputPath); err != nil {
64			t.Fatal(err)
65		}
66		return dir
67	}
68	
69	// generateAlertsCLI runs `alerts generate` for channel ops over the
70	// inclusive range 0..100 and requires a clean success.
71	func generateAlertsCLI(t *testing.T, dir, minSeverity string) cliResult {
72		t.Helper()
73		res := runCLI(t, "alerts", "generate", dir, "1", "0", "100", minSeverity, "ops")
74		if res.exitCode != 0 {
75			t.Fatalf("alerts generate (minSeverity %s) exit=%d stderr=%q", minSeverity, res.exitCode, res.stderr)
76		}
77		if strings.TrimSpace(res.stderr) != "" {
78			t.Fatalf("unexpected stderr: %q", res.stderr)
79		}
80		return res
81	}
82	
83	// parseAlertRecords requires stdout to be exactly one JSON array of
84	// processing records and returns it.
85	func parseAlertRecords(t *testing.T, raw string) []mevwatch.ProcessingRecord {
86		t.Helper()
87		trimmed := strings.TrimSpace(raw)
88		if !strings.HasPrefix(trimmed, "[") {
89			t.Fatalf("stdout is not a JSON array: %q", raw)
90		}
91		var records []mevwatch.ProcessingRecord
92		if err := json.Unmarshal([]byte(trimmed), &records); err != nil {
93			t.Fatalf("stdout is not valid JSON: %v\n%s", err, raw)
94		}
95		return records
96	}
97	
98	// wantSwap is the full raw field set of one evidence swap.
99	type wantSwap struct {
100		tx, pool, trader string
101		in, out, gas     int64
102		index            int
103	}
104	
105	func checkEvidence(t *testing.T, label string, got []mevwatch.Swap, want []wantSwap) {
106		t.Helper()
107		if len(got) != len(want) {
108			t.Fatalf("%s: got %d evidence swaps, want %d: %+v", label, len(got), len(want), got)
109		}
110		for i, w := range want {
111			s := got[i]
112			if s.TxHash != w.tx || s.Pool != w.pool || s.Trader != w.trader ||
113				s.In != w.in || s.Out != w.out || s.GasPrice != w.gas || s.Index != w.index {
114				t.Fatalf("%s: evidence[%d] = %+v, want tx=%s pool=%s trader=%s in=%d out=%d gas=%d index=%d",
115					label, i, s, w.tx, w.pool, w.trader, w.in, w.out, w.gas, w.index)
116			}
117		}
118	}
119	
120	// checkBuiltinVersion requires the record to carry the built-in detection
121	// version with its complete parameters — proof that generation consumed
122	// the archived conclusion instead of re-judging under the currently
123	// enabled version.
124	func checkBuiltinVersion(t *testing.T, label string, v mevwatch.RuleVersion) {
125		t.Helper()
126		if v.ID != mevwatch.BuiltinVersionID ||
127			!v.Rules.Sandwich.Enabled || v.Rules.Sandwich.Severity != 3 ||
128			!v.Rules.Displacement.Enabled || v.Rules.Displacement.Severity != 2 ||
129			v.Rules.Displacement.Multiplier != 2 {
130			t.Fatalf("%s: record must keep the archived builtin version with full params, got %+v", label, v)
131		}
132	}
133	
134	var (
135		sandwichEvidence = []wantSwap{
136			{"0xf", "p1", "bot", 500, 480, 90, 0},
137			{"0xv", "p1", "user", 200, 188, 10, 1},
138			{"0+k", "p1", "bot", 480, 505, 80, 2},
139		}
140		displacementEvidence = []wantSwap{
141			{"0+w", "p2", "whale", 700, 690, 50, 3},
142			{"0xd", "p2", "user", 300, 295, 10, 4},
143		}
144	)
145	
146	// TestCLIAlertsGenerateThresholdBackfill is the core scenario: threshold 3
147	// processes only the sandwich (severity equal to the threshold counts);
148	// lowering the threshold to 2 — after enabling a different rule version —
149	// backfills exactly the displacement, consuming the archived conclusion;
150	// a further run at threshold 2 finds nothing left.
151	func TestCLIAlertsGenerateThresholdBackfill(t *testing.T) {
152		dir := setupAlertsCLIArchive(t)
153	
154		// First generation at threshold 3: only the severity-3 sandwich.
155		res := generateAlertsCLI(t, dir, "3")
156		first := parseAlertRecords(t, res.stdout)
157		if len(first) != 1 {
158			t.Fatalf("threshold 3 produced %d records, want exactly the sandwich: %s", len(first), res.stdout)
159		}
160		sand := first[0]
161		if sand.ChainID != "1" || sand.BlockHash != "0xa" || sand.BlockNumber != 10 ||
162			sand.Channel != "ops" || sand.Pool != "p1" {
163			t.Fatalf("sandwich record identity wrong: %+v", sand)
164		}
165		if sand.Finding.Kind != "sandwich" || sand.Finding.TxHash != "0xv" || sand.Finding.Severity != 3 {
166			t.Fatalf("sandwich conclusion wrong: %+v", sand.Finding)
167		}
168		if sand.MinSeverity != 3 {
169			t.Fatalf("sandwich record threshold = %d, want 3", sand.MinSeverity)
170		}
171		if sand.Status != mevwatch.AlertStatusAlert {
172			t.Fatalf("sandwich status = %q, want alert", sand.Status)
173		}
174		if len(sand.Suppressions) != 0 || !strings.Contains(res.stdout, `"suppressions":[]`) {
175			t.Fatalf("no suppression matched: list must serialize as [], got %s", res.stdout)
176		}
177		checkBuiltinVersion(t, "first generation", sand.Version)
178		checkEvidence(t, "first generation", sand.Finding.Evidence, sandwichEvidence)
179	
180		// Between the two generations the user registers and enables a rule
181		// version with different parameters through the regular CLI.
182		specPath := filepath.Join(t.TempDir(), "strict.json")
183		const strict = `{"id":"strict","rules":{"sandwich":{"enabled":true,"severity":5},"displacement":{"enabled":true,"severity":4,"multiplier":5}}}`
184		if err := os.WriteFile(specPath, []byte(strict), 0o644); err != nil {
185			t.Fatal(err)
186		}
187		if res := runCLI(t, "rules", "register", dir, specPath); res.exitCode != 0 {
188			t.Fatalf("rules register: exit=%d stderr=%q", res.exitCode, res.stderr)
189		}
190		if res := runCLI(t, "rules", "enable", dir, "strict"); res.exitCode != 0 {
191			t.Fatalf("rules enable: exit=%d stderr=%q", res.exitCode, res.stderr)
192		}
193	
194		// Lowering the threshold to 2 backfills only the displacement: the
195		// first run's sandwich record must not be mixed in, and the skipped
196		// displacement was not permanently excluded.
197		res = generateAlertsCLI(t, dir, "2")
198		second := parseAlertRecords(t, res.stdout)
199		if len(second) != 1 {
200			t.Fatalf("threshold 2 backfill produced %d records, want exactly the displacement: %s", len(second), res.stdout)
201		}
202		disp := second[0]
203		if disp.Finding.Kind != "displacement" || disp.Finding.TxHash != "0xd" {
204			t.Fatalf("backfill must return only the displacement, got %+v", disp.Finding)
205		}
206		if disp.Finding.Severity != 2 {
207			t.Fatalf("backfill re-judged the archived conclusion: severity = %d, want 2", disp.Finding.Severity)
208		}
209		if disp.MinSeverity != 2 {
210			t.Fatalf("displacement record threshold = %d, want 2", disp.MinSeverity)
211		}
212		if disp.ChainID != "1" || disp.BlockHash != "0xa" || disp.BlockNumber != 10 ||
213			disp.Channel != "ops" || disp.Pool != "p2" {
214			t.Fatalf("displacement record identity wrong: %+v", disp)
215		}
216		if disp.Status != mevwatch.AlertStatusAlert {
217			t.Fatalf("displacement status = %q, want alert", disp.Status)
218		}
219		if len(disp.Suppressions) != 0 || !strings.Contains(res.stdout, `"suppressions":[]`) {
220			t.Fatalf("no suppression matched: list must serialize as [], got %s", res.stdout)
221		}
222		// The enabled strict version must not leak into the backfill: the
223		// record consumes the archived builtin conclusion and parameters.
224		checkBuiltinVersion(t, "backfill", disp.Version)
225		checkEvidence(t, "backfill", disp.Finding.Evidence, displacementEvidence)
226	
227		// After the backfill, generating again at threshold 2 yields [].
228		res = generateAlertsCLI(t, dir, "2")
229		if strings.TrimSpace(res.stdout) != "[]" {
230			t.Fatalf("post-backfill generation must print [], got %q", res.stdout)
231		}
232	
233		// History shows both records, each keeping the threshold of its own
234		// first processing, attributed to the user's channel.
235		res = runCLI(t, "alerts", "history", dir, "1", "ops", "0", "100")
236		if res.exitCode != 0 {
237			t.Fatalf("alerts history: exit=%d stderr=%q", res.exitCode, res.stderr)
238		}
239		hist := parseAlertRecords(t, res.stdout)
240		if len(hist) != 2 {
241			t.Fatalf("history holds %d records, want 2: %s", len(hist), res.stdout)
242		}
243		byKind := map[string]mevwatch.ProcessingRecord{}
244		for _, r := range hist {
245			if r.Channel != "ops" || r.ChainID != "1" || r.BlockHash != "0xa" || r.BlockNumber != 10 {
246				t.Fatalf("history record identity wrong: %+v", r)
247			}
248			if r.Status != mevwatch.AlertStatusAlert || len(r.Suppressions) != 0 {
249				t.Fatalf("history record status/suppressions wrong: %+v", r)
250			}
251			checkBuiltinVersion(t, "history "+r.Finding.Kind, r.Version)
252			byKind[r.Finding.Kind] = r
253		}
254		hs, okS := byKind["sandwich"]
255		hd, okD := byKind["displacement"]
256		if !okS || !okD {
257			t.Fatalf("history must hold both conclusions, got %+v", byKind)
258		}
259		if hs.MinSeverity != 3 || hd.MinSeverity != 2 {
260			t.Fatalf("records must keep first-processing thresholds 3 and 2, got %d and %d",
261				hs.MinSeverity, hd.MinSeverity)
262		}
263		if hs.Finding.Severity != 3 || hd.Finding.Severity != 2 {
264			t.Fatalf("history conclusions changed: %+v / %+v", hs.Finding, hd.Finding)
265		}
266		checkEvidence(t, "history sandwich", hs.Finding.Evidence, sandwichEvidence)
267		checkEvidence(t, "history displacement", hd.Finding.Evidence, displacementEvidence)
268	
269		// Records belong to the user's channel only.
270		res = runCLI(t, "alerts", "history", dir, "1", "other", "0", "100")
271		if res.exitCode != 0 || strings.TrimSpace(res.stdout) != "[]" {
272			t.Fatalf("other channel history must be [], exit=%d stdout=%q", res.exitCode, res.stdout)
273		}
274	
275		// The archived report itself is untouched: same conclusions, same
276		// evidence, still explained by the built-in version.
277		res = runCLI(t, "report", dir, "1", "0xa")
278		if res.exitCode != 0 {
279			t.Fatalf("report: exit=%d stderr=%q", res.exitCode, res.stderr)
280		}
281		var report mevwatch.Report
282		if err := json.Unmarshal([]byte(res.stdout), &report); err != nil {
283			t.Fatalf("report stdout is not valid JSON: %v\n%s", err, res.stdout)
284		}
285		checkBuiltinVersion(t, "report", report.Version)
286		if len(report.Findings) != 2 {
287			t.Fatalf("report findings changed: %+v", report.Findings)
288		}
289		reportByKind := map[string]mevwatch.ReportFinding{}
290		for _, f := range report.Findings {
291			reportByKind[f.Kind] = f
292		}
293		if reportByKind["sandwich"].Severity != 3 || reportByKind["sandwich"].TxHash != "0xv" ||
294			reportByKind["displacement"].Severity != 2 || reportByKind["displacement"].TxHash != "0xd" {
295			t.Fatalf("report conclusions changed by alerting: %+v", report.Findings)
296		}
297		checkEvidence(t, "report sandwich", reportByKind["sandwich"].Evidence, sandwichEvidence)
298		checkEvidence(t, "report displacement", reportByKind["displacement"].Evidence, displacementEvidence)
299	}
300	
301	// TestCLIAlertsGenerateInvalidThreshold covers the failure shapes: a
302	// non-integer threshold is an argument error, an integer outside 1..5 is a
303	// threshold-range error; both exit non-zero, explain themselves on stderr
304	// and print no success records. The failures leave existing alerts and
305	// still-pending conclusions untouched, so a later valid threshold produces
306	// exactly the expected backfill.
307	func TestCLIAlertsGenerateInvalidThreshold(t *testing.T) {
308		dir := setupAlertsCLIArchive(t)
309	
310		// One successful generation first, so the failures below have existing
311		// alerts to protect and the displacement stays pending.
312		res := generateAlertsCLI(t, dir, "3")
313		if got := parseAlertRecords(t, res.stdout); len(got) != 1 {
314			t.Fatalf("precondition: threshold 3 produced %d records, want 1", len(got))
315		}
316	
317		cases := []struct {
318			name     string
319			arg      string
320			wantCode int
321			wantErr  string
322		}{
323			{"non-integer", "abc", 2, "invalid minSeverity"},
324			{"fractional", "2.5", 2, "invalid minSeverity"},
325			{"zero", "0", 1, "minSeverity must be between 1 and 5"},
326			{"negative", "-1", 1, "minSeverity must be between 1 and 5"},
327			{"above range", "6", 1, "minSeverity must be between 1 and 5"},
328		}
329		for _, tc := range cases {
330			t.Run(tc.name, func(t *testing.T) {
331				res := runCLI(t, "alerts", "generate", dir, "1", "0", "100", tc.arg, "ops")
332				if res.exitCode != tc.wantCode {
333					t.Fatalf("exit = %d, want %d; stdout=%q stderr=%q",
334						res.exitCode, tc.wantCode, res.stdout, res.stderr)
335				}
336				if res.stdout != "" {
337					t.Fatalf("failed generation must print no success records, got %q", res.stdout)
338				}
339				if !strings.Contains(res.stderr, tc.wantErr) {
340					t.Fatalf("stderr = %q, want substring %q", res.stderr, tc.wantErr)
341				}
342			})
343		}
344	
345		// The failures changed nothing: history still holds exactly the
346		// sandwich alert from the first generation...
347		res = runCLI(t, "alerts", "history", dir, "1", "ops", "0", "100")
348		if res.exitCode != 0 {
349			t.Fatalf("alerts history: exit=%d stderr=%q", res.exitCode, res.stderr)
350		}
351		hist := parseAlertRecords(t, res.stdout)
352		if len(hist) != 1 || hist[0].Finding.Kind != "sandwich" || hist[0].MinSeverity != 3 {
353			t.Fatalf("failed generations damaged stored alerts: %+v", hist)
354		}
355	
356		// ...and the still-pending displacement backfills normally with a
357		// valid threshold.
358		res = generateAlertsCLI(t, dir, "2")
359		backfill := parseAlertRecords(t, res.stdout)
360		if len(backfill) != 1 || backfill[0].Finding.Kind != "displacement" ||
361			backfill[0].Finding.TxHash != "0xd" || backfill[0].MinSeverity != 2 {
362			t.Fatalf("post-failure backfill wrong: %+v", backfill)
363		}
364	}
